GimCorpus.put(508,0,[[1,3,"יראה לי שאין הדברים אמורים אלא בחרובי צלמונה כו'. עיין לעיל בפרק א' מהלכות מעשר דין ט':",1,0],[1,11,"פירות שנה שניה שנתערבו וכו'. גרסי' בתוס' פ\"ד דדמאי מצרפין פירות ח\"ל על פירות שניה כדי שירבו על פירות שלישית לפוטרן מן מעשר שני מצרפין מפירות ח\"ל על פירות שלישית כדי שירבו על פירות רביעית לפוטרן מן מעשר עני ע\"כ:",1,0],[1,12,"כל הפטור ממעשר ראשון פטור מן השני כו'. וכן כל הפטור מן התורה ממעשר ראשון פטור מן התורה ממע\"ש. והוצרכתי לזה לפי שראיתי לסמ\"ג עשין קל\"ו שכתב דבספרי פרשת ראה משמע דמע\"ש נוהג בכל דבר ומשמע מדבריו שם דאפילו בירק נוהג מע\"ש מן התורה וכל כך הוחזק דין זה בעיניו עד שבעשין קס\"א גבי מע\"ע כתב אע\"פ שבספרי משמע דמע\"ש נוהג מן התורה אפילו בירקות זהו מפני רבוי המקראות אשר שם אבל במע\"ע שלא מצינו רבוי יש להשוותם לתרומה ולמעשר ראשון ע\"כ. ודין זה הוא תימה בעיני לחלק בין מע\"ש לשאר מעשרות ולא ראיתי לשום אחד מגדולי המורים שחילקו חילוק זה ואין ספק אצלי דהראשונים ז\"ל דלא חילקו חילוק זה סוברים דברייתא הלזו אסמכתא בעלמא היא. וראיתי להרמב\"ן פרשת ראה שכתב וז\"ל ויש ברייתות שנויות בת\"כ ובספרי לאסמכתות והן מטעות ע\"כ. ( א\"ה וכ\"כ בתוס' פ\"ט דבכורות (דף נ\"ד) ד\"ה ושני ובשבת (דף ס\"ח) ד\"ה ואלו דכל הני דרשות דספרי אסמכתא בעלמא נינהו ועיין בתוס' עירובין (דף ל\"ז) ד\"ה מאן ובע\"ז (דף נ\"ח) ד\"ה בצר:",1,0],[2,1,"אבל אינו נאכל בירושלים אלא בפני הבית כו'. לקמן פ\"ו מהלכות בית הבחירה דין י\"ד ובדברי הראב\"ד שם ובמה שרמזתי שם ודוק. ועיין בסוף ספר קרבן חגיגה (דף נ\"ה):",1,0],[2,9,"עבר והוציאן. חולין (דף סח):",1,0],[2,16,"והחלונות ועובי החומה כלפנים. עיין פ\"ו מהלכות בית הבחירה דין ט' ובפרק י' מהלכות מעשה הקרבנות דין ה' ובר\"פ ט' מהלכות קרבן פסח:",1,0],[3,4,"הערל כטמא כו'. עיין במה שכתב הרב לח\"מ פ\"ב מהלכות חגיגה:",1,0],[3,5,"האוכל מע\"ש באנינות של תורה. עיין בסמ\"ג לאוין סי' רנ\"ט:",1,0],[3,8,"אין מפקידין מעשר כו'. מ\"ש הראב\"ד ועכ\"ז אין דעתי נוחה הימנו אלא במעות שהוא פקדון ארוך כו'. עיין במ\"ש הרא\"ש פ\"ק דנדרים אההיא דלא אפטר מן העולם עד שאהיה נזיר דאמרינן לאלתר הוי נזיר דילמא השתא מיית ואפילו מאן דפליג בפרק כל הגט ואמר לא חיישינן שמא ימות הכא לזמן מרובה דל' ימי נזירות חיישינן ע\"כ. כלומר דדוקא האומר ה\"ז גיטך שעה אחת בעולם קודם מיתתי איכא מ\"ד דמותרת לאכול בתרומה מיד משום שהחששא היא שמא ימות באותה שעה וכל שלא מת באותה שעה בהיתר אכלה התרומה וכן בההיא דשני לוגין החששא היא שמא יבקע הנוד תיכף לשתייתו ומ\"ש לא חייש אבל הכא דהחששא היא שמא ימות בתוך ל' יום דנמצא דלא קיים נדרו אליבא דכ\"ע חיישינן שמא ימות. ולפי זה האומר ה\"ז גיטך ל' יום קודם מיתתי אליבא דכ\"ע אסורה לאכול בתרומה מיד ודוק:",1,0],[3,23,"אומר אדם לחבירו בירושלים לסוך אותו כו'. ( א\"ה עיין לעיל פי\"א מה' תרומות דין ח'):",1,0],[5,4,"מעשר שני שאין בחומשו שוה פרוטה. עיין מה שכתב הרב לח\"מ רפ\"ה מהל' ערכין:",1,0],[6,14,"לפיכך אם נתערבו בירושלים כו'. דין זה לכאורה סותר למ\"ש בסוף הפרק דלא חשיב דבר שיש לו מתירין אלא היכא דאינו יכול להכניסו ועיין פ\"ח י\"ד סי' ק\"ב ס\"ק ח'. כתב מרן ומ\"ש כמנין נראה דה\"פ כו'. ולי נראה שהוא ט\"ס ועיקר הגירסא היא במינם לפי שדבר שיש לו מתירין אינו אוסר כי אם במינו וכמ\"ש רבינו בהלכות מאכלות אסורות וכ\"כ לקמן בפרק ד' מהלכות בכורים דין ט\"ו וזה פשוט ועיין בתי\"ט ובפרק ח' שם:",1,0],[6,16,"באיזה מעשר אמרו כו'. עיין לקמן פרק ו' מהלכות בית הבחירה דין ט\"ו והראב\"ד שם ובמה שרמזתי שם ודוק:",1,0],[7,15,"הלוקח פירות חוץ לירושלים וכו'. עיין במקום הנזכר ובמה שרמזתי שם ודו\"ק:",1,0],[9,2,"ואין פודין אותו במחובר כו'. עיין בירושלמי פ\"ק דפיאה אמתני' דנותנין פיאה ודוק:",1,0],[10,21,"שכל דבר שיש לו שני גורמים וכו'. עיין במה שכתב הראב\"ד לעיל ספ\"ה מה' נדרים:",1,0],[11,11,"מי שהיו פירותיו רחוקים ממנו כו'. הכי איתא בפ\"ק דמציעא (דף י\"ב) מתנות כהונה נתינה כתיב בהו חליפין דרך מקח וממכר הוא מטלטלי אגב מקרקעי נתינה אלימתא היא ע\"כ. ורבינו לא ס\"ל כרבא דטובת הנאה אינה ממון לקנות בחליפין או ע\"ג קרקע משום דאזיל לשיטתיה שפסק בהלכות זכייה ומתנה דלעולם בעינן עומד בצד שדהו אפילו בחצר המשתמרת וא\"כ ע\"כ עובדא דר\"ג וזקנים מטלטלי אגב מקרקע הקנה להם ועיין במ\"ש מרן בח\"מ סי' קצ\"ה ס\"ח בשם בעל העיטור. ודע שאינו צריך לסיים מקום בצפונו או בדרומו ואע\"ג דלענין איסורא דטבל לא מהני עד שיסיים מקום וכמ\"ש רבינו בפ\"ג מהלכות תרומות דין ח' מ\"מ לענין חיובא דמצות ביעור סגי בקריאת שם לבד כן מתבאר מדברי התוס' פ\"ק דקידושין (דף כ\"ו) ד\"ה מעשה. אך ראיתי להריטב\"א שם בחידושיו שכתב ואיכא דקשיא ליה איך לא סיים מקום למעשרות אלו כו' ואיכא למימר דכי בעינן סיום מקום ה\"מ למאן דלית ליה ברירה אבל ר\"ג סבר יש ברירה וכשאוכל ומשייר שיעור מעשר אמרינן הוברר הדבר למפרע שזהו מה שהפריש ע\"כ. ולפ\"ז לדידן דקי\"ל דאין ברירה צריך לסיים מקום: סליקו להו הלכות מעשר שני ונטע רבעי",1,0]]);
